def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import defaultdict
    by=defaultdict(list)
    for r in range(h):
        for c in range(w):
            by[g[r][c]].append((r,c))
    for color,pts in by.items():
        if color in (0,6,7,9): continue
        pairs=[]
        for i,(r,c) in enumerate(pts):
            for rr,cc in pts[i+1:]:
                dr,dc=rr-r,cc-c
                if dr!=0 and abs(dr)==abs(dc): pairs.append((r,c,rr,cc))
        if not pairs: continue
        r,c,rr,cc=pairs[0]
        sr=1 if rr>r else -1; sc=1 if cc>c else -1
        ar,ac=r-sr,c-sc
        while 0<=ar<h and 0<=ac<w:
            g[ar][ac]=color; ar-=0 # avoid
            ar-=sr; ac-=sc
        ar,ac=rr+sr,cc+sc
        while 0<=ar<h and 0<=ac<w:
            g[ar][ac]=color; ar+=sr; ac+=sc
    return g
